#!/usr/bin/env python3
"""Render one run.yaml per example case from a manifest and a template.

The manifest names every case directory, its extxyz substrate and its site
selection; the template carries the shared protocol, filters and rotamer
settings. The rendered files are generated artifacts (ignored by git), so
editing the manifest or the template is enough to change every case.
"""

from __future__ import annotations

import argparse
import sys
from collections.abc import Iterator
from pathlib import Path
from typing import Any

import yaml

HEADER = (
    "# Generated by examples/build_cases.py from manifest.yaml + "
    "run.yaml.template.\n"
    "# This file is ignored by git; edit the manifest or the template "
    "instead.\n"
)


def deep_merge(
    base: dict[str, Any],
    override: dict[str, Any],
) -> dict[str, Any]:
    """Return ``base`` with ``override`` applied recursively."""
    merged = dict(base)
    for key, value in override.items():
        current = merged.get(key)
        if isinstance(value, dict) and isinstance(current, dict):
            merged[key] = deep_merge(current, value)
        else:
            merged[key] = value
    return merged


def iter_cases(
    family: Path,
    manifest: dict[str, Any],
) -> Iterator[tuple[Path, dict[str, Any], str]]:
    """Yield ``(case_dir, site_spec, adsorbate_name)`` for every case."""
    adsorbates = manifest["adsorbates"]
    layout = manifest.get("layout", "single")
    if layout == "single":
        specs = manifest["sites"]
        for site_dir in sorted(p for p in family.iterdir() if p.is_dir()):
            if site_dir.name not in specs:
                continue
            for ads_dir in sorted(p for p in site_dir.iterdir() if p.is_dir()):
                if ads_dir.name in adsorbates:
                    yield ads_dir, specs[site_dir.name], ads_dir.name
        return
    specs = manifest["systems"]
    for system_dir in sorted(p for p in family.iterdir() if p.is_dir()):
        if system_dir.name not in specs:
            continue
        for ads_dir in sorted(p for p in system_dir.iterdir() if p.is_dir()):
            if ads_dir.name in adsorbates:
                yield ads_dir, specs[system_dir.name], ads_dir.name


def render(
    template: dict[str, Any],
    manifest: dict[str, Any],
    family: Path,
    site_spec: dict[str, Any],
    adsorbate: str,
) -> dict[str, Any]:
    """Return the merged configuration of one case."""
    substrate = (family / str(site_spec["substrate"])).resolve()
    sites = site_spec.get("sites")
    if sites is None:
        sites = [list(site_spec["core"])]
    case = {
        "substrate": {
            "_target_": "ase.io.read",
            "filename": str(substrate),
            "format": "extxyz",
        },
        "adsorbate": {"smiles": manifest["adsorbates"][adsorbate]},
        "sites": sites,
    }
    return deep_merge(template, case)


def main(argv: list[str] | None = None) -> int:
    """Render the cases.

    Args:
        argv: Optional argument list, defaults to ``sys.argv[1:]``.

    Returns:
        int: Process exit status.
    """
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("manifest", help="Family manifest YAML.")
    parser.add_argument("template", help="Shared run.yaml template.")
    parser.add_argument(
        "--root",
        default=None,
        help="Family directory; defaults to the manifest parent.",
    )
    parser.add_argument(
        "--check",
        action="store_true",
        help="Do not write; exit 1 when at least one case would change.",
    )
    args = parser.parse_args(argv)

    manifest_path = Path(args.manifest)
    manifest = yaml.safe_load(manifest_path.read_text(encoding="utf-8"))
    template = yaml.safe_load(Path(args.template).read_text(encoding="utf-8"))
    if not isinstance(manifest, dict) or not isinstance(template, dict):
        print("manifest and template must be YAML mappings.", file=sys.stderr)
        return 2
    family = (
        manifest_path.parent if args.root is None else Path(args.root).resolve()
    )

    changed: list[Path] = []
    total = 0
    for case_dir, site_spec, adsorbate in iter_cases(family, manifest):
        total += 1
        data = render(template, manifest, family, site_spec, adsorbate)
        path = case_dir / "run.yaml"
        existing = None
        if path.exists():
            existing = yaml.safe_load(path.read_text(encoding="utf-8"))
        if existing == data:
            continue
        changed.append(path)
        if args.check:
            continue
        path.write_text(
            HEADER + yaml.safe_dump(data, sort_keys=False, allow_unicode=True),
            encoding="utf-8",
        )
    print(f"rendered {total} cases, updated {len(changed)}")
    if args.check and changed:
        joined = ", ".join(str(path) for path in changed)
        print(f"cases would change: {joined}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
